CREATE OR REPLACE FUNCTION public.check_username_availability (
  candidate text
)
  RETURNS TABLE (
    available boolean,
    reason    text
  )
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO 'public'
  AS $function$
declare
  normalized text := lower(trim(candidate));
begin
  if normalized !~ '^[a-z0-9_]{3,30}$' then
    return query select false, 'format';
    return;
  end if;

  if exists (
    select 1
    from public.reserved_usernames r
    where lower(r.username) = normalized
  ) then
    return query select false, 'reserved';
    return;
  end if;

  if exists (
    select 1
    from public.user u
    where lower(u.username) = normalized
  ) then
    return query select false, 'taken';
    return;
  end if;

  return query select true, null::text;
end;
$function$;

CREATE OR REPLACE FUNCTION public.complete_onboarding (
  p_username        text,
  p_birth_date      date,
  p_gender          text,
  p_profile_picture text,
  p_latitude        double precision,
  p_longitude       double precision,
  p_category_ids    bigint[]
)
  RETURNS void
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
    v_user_id uuid;
    v_location_id bigint;
begin
    v_user_id := auth.uid();

    if v_user_id is null then
        raise exception 'Utilisateur non authentifié';
    end if;

    /*
     * La ligne public.user existe déjà grâce à handle_new_user.
     */
    select id_location
    into v_location_id
    from public."user"
    where id = v_user_id;

    if not found then
        raise exception 'Profil utilisateur introuvable';
    end if;

    /*
     * Création ou actualisation de la localisation.
     * PostGIS attend POINT(longitude latitude).
     */
    if p_latitude is not null and p_longitude is not null then
        if v_location_id is null then
            insert into public.user_location (location)
            values (
                extensions.st_setsrid(
                    extensions.st_makepoint(
                        p_longitude,
                        p_latitude
                    ),
                    4326
                )::extensions.geography
            )
            returning id into v_location_id;
        else
            update public.user_location
            set
                location = extensions.st_setsrid(
                    extensions.st_makepoint(
                        p_longitude,
                        p_latitude
                    ),
                    4326
                )::extensions.geography,
                last_updated = now()
            where id = v_location_id;
        end if;
    end if;

    /*
     * Mise à jour de la ligne créée par le trigger d'inscription.
     */
    update public."user"
    set
        username = lower(trim(p_username)),
        birth_date = p_birth_date,
        gender = nullif(trim(p_gender), ''),
        profile_picture = p_profile_picture,
        id_location = v_location_id,
        has_completed_onboarding = true
    where id = v_user_id;

    if not found then
        raise exception 'Profil utilisateur introuvable';
    end if;

    /*
     * Remplacement des préférences précédentes.
     */
    delete from public.user_category_preferences
    where id_user = v_user_id;

    insert into public.user_category_preferences (
        id_user,
        id_category
    )
    select
        v_user_id,
        selected.id_category
    from unnest(
        coalesce(p_category_ids, array[]::bigint[])
    ) as selected(id_category)
    on conflict (id_user, id_category) do nothing;
end;
$function$;

CREATE OR REPLACE FUNCTION public.create_product_transaction (
  p_owner_id    uuid,
  p_name        text,
  p_description text,
  p_category_id bigint,
  p_state_id    bigint,
  p_city        text,
  p_postcode    text,
  p_department  text,
  p_latitude    double precision,
  p_longitude   double precision,
  p_attributes  jsonb,
  p_photos      jsonb
)
  RETURNS bigint
  LANGUAGE plpgsql
  SET search_path TO 'pg_catalog', 'public', 'extensions'
  AS $function$
declare
  v_product_id bigint;
  v_attr jsonb;
  v_value text;
  v_allowed record;
  v_values text[];
  v_seen bigint[] := '{}';
  v_required_count integer;
  v_received_required_count integer;
  v_state_valid boolean;
  v_state_has_is_active boolean;
  v_photo jsonb;
  v_photo_position integer;
  v_photo_path text;
  v_photo_count integer;
  v_owner_text text;
begin
  v_owner_text := p_owner_id::text;

  if p_owner_id is null then
    raise exception 'OWNER_REQUIRED';
  end if;

  if p_name is null
     or btrim(p_name) = ''
     or char_length(btrim(p_name)) > 120 then
    raise exception 'INVALID_NAME';
  end if;

  if p_description is null
     or btrim(p_description) = ''
     or char_length(btrim(p_description)) > 5000 then
    raise exception 'INVALID_DESCRIPTION';
  end if;

  if p_city is null
     or btrim(p_city) = ''
     or char_length(btrim(p_city)) > 120 then
    raise exception 'INVALID_CITY';
  end if;

  if p_postcode is null
     or btrim(p_postcode) = ''
     or char_length(btrim(p_postcode)) > 20 then
    raise exception 'INVALID_POSTCODE';
  end if;

  if p_department is null
     or btrim(p_department) = ''
     or char_length(btrim(p_department)) > 120 then
    raise exception 'INVALID_DEPARTMENT';
  end if;

  if p_latitude is null
     or p_latitude <> p_latitude
     or p_latitude < -90
     or p_latitude > 90
     or p_longitude is null
     or p_longitude <> p_longitude
     or p_longitude < -180
     or p_longitude > 180 then
    raise exception 'INVALID_COORDINATES';
  end if;

  if p_attributes is null
     or jsonb_typeof(p_attributes) <> 'array' then
    raise exception 'INVALID_ATTRIBUTES_ARRAY';
  end if;

  if p_photos is null
     or jsonb_typeof(p_photos) <> 'array' then
    raise exception 'INVALID_PHOTOS_ARRAY';
  end if;

  v_photo_count := jsonb_array_length(p_photos);

  if v_photo_count < 1 or v_photo_count > 10 then
    raise exception 'INVALID_PHOTO_COUNT';
  end if;


  /*
    Vérification des photos :
    products/{ownerId}/{uploadUuid}/{position}.jpg
  */
  for v_photo in
    select value
    from jsonb_array_elements(p_photos)
  loop
    if jsonb_typeof(v_photo) <> 'object'
       or jsonb_typeof(v_photo->'path') <> 'string'
       or jsonb_typeof(v_photo->'position') <> 'number' then
      raise exception 'INVALID_PHOTO_OBJECT';
    end if;

    v_photo_path := v_photo->>'path';
    v_photo_position := (v_photo->>'position')::integer;

    if v_photo_position < 1
       or v_photo_position > v_photo_count then
      raise exception 'INVALID_PHOTO_POSITION';
    end if;

    if v_photo_path !~ (
      '^products/'
      || v_owner_text
      || '/[0-9a-fA-F-]{36}/'
      || v_photo_position::text
      || '\.jpg$'
    ) then
      raise exception 'INVALID_PHOTO_PATH';
    end if;
  end loop;

  if exists (
    select 1
    from jsonb_array_elements(p_photos) photo
    group by (photo->>'position')::integer
    having count(*) > 1
  ) then
    raise exception 'DUPLICATE_PHOTO_POSITION';
  end if;

  if (
    select count(*)
    from jsonb_array_elements(p_photos) photo
    where (photo->>'position')::integer
      between 1 and v_photo_count
  ) <> v_photo_count then
    raise exception 'PHOTO_POSITIONS_MUST_BE_CONTIGUOUS';
  end if;


  if not exists (
    select 1
    from public.category c
    where c.id = p_category_id
      and c.is_active = true
  ) then
    raise exception 'INVALID_CATEGORY';
  end if;


  select exists (
    select 1
    from information_schema.columns
    where table_schema = 'public'
      and table_name = 'state'
      and column_name = 'is_active'
  )
  into v_state_has_is_active;

  if v_state_has_is_active then
    execute '
      select exists (
        select 1
        from public.state
        where id = $1
          and is_active = true
      )
    '
    into v_state_valid
    using p_state_id;
  else
    select exists (
      select 1
      from public.state
      where id = p_state_id
    )
    into v_state_valid;
  end if;

  if not v_state_valid then
    raise exception 'INVALID_STATE';
  end if;


  /*
    Validation des attributs.
  */
  if exists (
    select 1
    from jsonb_array_elements(p_attributes) a
    where jsonb_typeof(a->'attributeId') <> 'number'
       or jsonb_typeof(a->'values') <> 'array'
  ) then
    raise exception 'INVALID_ATTRIBUTE_OBJECT';
  end if;

  select count(*)
  into v_required_count
  from public.category_attributes_resolved car
  where car.id_category = p_category_id
    and car.required = true;

  select count(*)
  into v_received_required_count
  from (
    select distinct
      (a->>'attributeId')::bigint as attribute_id
    from jsonb_array_elements(p_attributes) a
  ) received
  where exists (
    select 1
    from public.category_attributes_resolved car
    where car.id_category = p_category_id
      and car.required = true
      and car.id_attribute_def = received.attribute_id
  );

  if v_received_required_count <> v_required_count then
    raise exception 'REQUIRED_ATTRIBUTE_MISSING';
  end if;

  for v_attr in
    select value
    from jsonb_array_elements(p_attributes)
  loop
    if (v_attr->>'attributeId')::bigint = any(v_seen) then
      raise exception 'DUPLICATE_ATTRIBUTE';
    end if;

    v_seen := array_append(
      v_seen,
      (v_attr->>'attributeId')::bigint
    );

    select *
    into v_allowed
    from public.category_attributes_resolved car
    where car.id_category = p_category_id
      and car.id_attribute_def = (v_attr->>'attributeId')::bigint;

    if not found then
      raise exception 'ATTRIBUTE_NOT_ALLOWED';
    end if;

    select array_agg(value)
    into v_values
    from jsonb_array_elements_text(v_attr->'values') value;

    if v_values is null
       or cardinality(v_values) = 0 then
      raise exception 'ATTRIBUTE_VALUE_REQUIRED';
    end if;

    if v_allowed.input_type not in ('select', 'multi_select')
       and cardinality(v_values) <> 1 then
      raise exception 'TEXT_ATTRIBUTE_REQUIRES_ONE_VALUE';
    end if;

    if v_allowed.input_type in ('select', 'multi_select') then

      if coalesce(jsonb_typeof(v_allowed.options), 'null') <> 'array' then
        raise exception 'ATTRIBUTE_OPTIONS_MUST_BE_ARRAY';
      end if;

      if v_allowed.input_type = 'select'
         and cardinality(v_values) <> 1 then
        raise exception 'SELECT_REQUIRES_ONE_VALUE';
      end if;

      if v_allowed.input_type = 'multi_select'
         and cardinality(v_values) < 1 then
        raise exception 'MULTI_SELECT_REQUIRES_AT_LEAST_ONE_VALUE';
      end if;

      if exists (
        select 1
        from unnest(v_values) submitted_value
        where not exists (
          select 1
          from jsonb_array_elements_text(v_allowed.options) allowed_value
          where allowed_value = submitted_value
        )
      ) then
        raise exception 'ATTRIBUTE_VALUE_NOT_ALLOWED';
      end if;

    end if;
  end loop;


  insert into public.product (
    name,
    description,
    price_trocoin,
    is_active,
    id_state,
    id_category,
    id_user
  )
  values (
    btrim(p_name),
    btrim(p_description),
    0,
    false,
    p_state_id,
    p_category_id,
    p_owner_id
  )
  returning id into v_product_id;


  insert into public.product_location (
    product_id,
    location,
    city,
    postcode,
    department
  )
  values (
    v_product_id,
    extensions.st_setsrid(
      extensions.st_makepoint(
        p_longitude,
        p_latitude
      ),
      4326
    )::extensions.geography,
    btrim(p_city),
    btrim(p_postcode),
    btrim(p_department)
  );


  insert into public.product_attributes (
    id_product,
    id_attribute_def,
    product_attribute_value
  )
  select
    v_product_id,
    (attribute_json->>'attributeId')::bigint,
    value_text
  from jsonb_array_elements(p_attributes) attribute_json
  cross join lateral jsonb_array_elements_text(
    attribute_json->'values'
  ) value_text;


  insert into public.product_photos (
    url,
    order_position,
    id_product
  )
  select
    photo_json->>'path',
    (photo_json->>'position')::smallint,
    v_product_id
  from jsonb_array_elements(p_photos) photo_json;


  update public.product
  set is_active = true
  where id = v_product_id;

  return v_product_id;
end;
$function$;

CREATE OR REPLACE FUNCTION public.ensure_active_product_has_location()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SET search_path TO 'pg_catalog', 'public'
  AS $function$
declare
  v_product_id bigint;
begin
  if tg_table_name = 'product' then
    v_product_id := coalesce(
      (to_jsonb(new) ->> 'id')::bigint,
      (to_jsonb(old) ->> 'id')::bigint
    );

  elsif tg_table_name = 'product_location' then
    v_product_id := coalesce(
      (to_jsonb(new) ->> 'product_id')::bigint,
      (to_jsonb(old) ->> 'product_id')::bigint
    );

  else
    raise exception 'UNSUPPORTED_TRIGGER_TABLE'
      using errcode = '0A000';
  end if;

  if exists (
    select 1
    from public.product p
    where p.id = v_product_id
      and p.is_active = true
      and not exists (
        select 1
        from public.product_location pl
        where pl.product_id = p.id
      )
  ) then
    raise exception 'ACTIVE_PRODUCT_REQUIRES_LOCATION'
      using errcode = '23514';
  end if;

  if tg_op = 'DELETE' then
    return old;
  end if;

  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION public.get_feed_filter_options (
  p_category_id bigint DEFAULT NULL::bigint
)
  RETURNS TABLE (
    kind         text,
    key          text,
    id           text,
    name         text,
    input_type   text,
    multiple     boolean,
    option_id    text,
    option_name  text,
    option_value text
  )
  LANGUAGE sql
  STABLE
  SET search_path TO 'pg_catalog', 'public'
  AS $function$
  WITH available_states AS (
    SELECT DISTINCT
      s.id::text AS id,
      s.name,
      s.slug
    FROM public.state AS s
    JOIN public.product AS p
      ON p.id_state = s.id
    WHERE p.is_active = true
      AND (p_category_id IS NULL OR p.id_category = p_category_id)
  ),
  resolved_attributes AS (
    SELECT DISTINCT
      ad.code,
      ad.id::text AS id,
      car.name,
      car.input_type,
      ad.options,
      CASE
        WHEN lower(coalesce(car.input_type, '')) IN (
          'multi_select', 'multiselect', 'checkbox', 'checkboxes',
          'checkbox_group', 'multi-checkbox', 'multi_checkbox'
        ) THEN true
        ELSE false
      END AS multiple
    FROM public.category_attributes_resolved AS car
    JOIN public.attributes_definitions AS ad
      ON ad.id = car.id_attribute_def
    WHERE p_category_id IS NOT NULL
      AND car.id_category = p_category_id
  )
  SELECT
    'condition'::text AS kind,
    'condition'::text AS key,
    st.id,
    st.name,
    'select'::text AS input_type,
    false AS multiple,
    NULL::text AS option_id,
    NULL::text AS option_name,
    NULL::text AS option_value
  FROM available_states AS st

  UNION ALL

  SELECT
    'attribute'::text AS kind,
    ra.code AS key,
    ra.id,
    ra.name,
    ra.input_type,
    ra.multiple,
    opt.value AS option_id,
    opt.value AS option_name,
    opt.value AS option_value
  FROM resolved_attributes AS ra
  LEFT JOIN LATERAL unnest(ra.options) AS opt(value)
    ON true
  ORDER BY kind, key, option_value NULLS FIRST;
$function$;

CREATE OR REPLACE FUNCTION public.get_product_locations_public (
  p_product_ids bigint[] DEFAULT NULL::bigint[],
  p_limit       integer  DEFAULT 100,
  p_offset      integer  DEFAULT 0
)
  RETURNS TABLE (
    product_id      bigint,
    city            text,
    postcode        text,
    department      text,
    distance_meters double precision
  )
  LANGUAGE sql
  STABLE
  SECURITY DEFINER
  SET search_path TO 'pg_catalog', 'public', 'extensions'
  AS $function$
  select
    p.id as product_id,
    pl.city,
    pl.postcode,
    pl.department,
    case
      when viewer.location is null then null::double precision
      else extensions.st_distance(pl.location, viewer.location)
    end as distance_meters
  from public.product p
  join public.product_location pl
    on pl.product_id = p.id
  left join lateral (
    select ul.location
    from public.user u
    join public.user_location ul
      on ul.id = u.id_location
    where u.id = auth.uid()
    limit 1
  ) viewer on true
  where p.is_active = true
    and (
      p_product_ids is null
      or p.id = any (p_product_ids)
    )
  order by
    case
      when viewer.location is null then null
      else extensions.st_distance(pl.location, viewer.location)
    end asc nulls last,
    p.id asc
  limit greatest(least(coalesce(p_limit, 100), 500), 1)
  offset greatest(coalesce(p_offset, 0), 0);
$function$;

CREATE OR REPLACE FUNCTION public.get_public_user_profile (
  p_username text
)
  RETURNS jsonb
  LANGUAGE sql
  STABLE
  SECURITY DEFINER
  SET search_path TO 'pg_catalog', 'public', 'extensions'
  AS $function$
  SELECT jsonb_build_object(
    'id', u.id,
    'username', u.username,
    'avatarUrl', u.profile_picture,
    'bannerUrl', u.profile_header,
    'bio', u.bio,
    'location', CASE
      WHEN ul.location IS NULL THEN NULL
      ELSE extensions.st_astext(ul.location)
    END,
    'createdAt', u.created_at,
    'trocsCount', (
      SELECT count(*)::integer
      FROM public.troc t
      WHERE t.status = 'completed'
        AND (
          t.id_user_initiator = u.id
          OR t.id_user_receiver = u.id
        )
    ),
    'followersCount', (
      SELECT count(*)::integer
      FROM public.user_follows uf
      WHERE uf.id_user_followed = u.id
    ),
    'followingCount', (
      SELECT count(*)::integer
      FROM public.user_follows uf
      WHERE uf.id_user_follower = u.id
    ),
    'reviewsCount', (
      SELECT count(*)::integer
      FROM public.user_evaluations ue
      WHERE ue.id_user_evaluated = u.id
    ),
    'reviewsRating', (
      SELECT round(avg(ue.rating)::numeric, 2)
      FROM public.user_evaluations ue
      WHERE ue.id_user_evaluated = u.id
    )
  )
  FROM public.user u
  LEFT JOIN public.user_location ul
    ON ul.id = u.id_location
  WHERE u.username = p_username;
$function$;

CREATE OR REPLACE FUNCTION public.handle_new_user()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$begin
  insert into public.user (id, email)
  values (new.id, new.email);
  return new;
end;$function$;

CREATE OR REPLACE FUNCTION public.rls_auto_enable()
  RETURNS event_trigger
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO 'pg_catalog'
  AS $function$
DECLARE
  cmd record;
BEGIN
  FOR cmd IN
    SELECT *
    FROM pg_event_trigger_ddl_commands()
    WHERE command_tag IN ('CREATE TABLE', 'CREATE TABLE AS', 'SELECT INTO')
      AND object_type IN ('table','partitioned table')
  LOOP
     IF cmd.schema_name IS NOT NULL AND cmd.schema_name IN ('public') AND cmd.schema_name NOT IN ('pg_catalog','information_schema') AND cmd.schema_name NOT LIKE 'pg_toast%' AND cmd.schema_name NOT LIKE 'pg_temp%' THEN
      BEGIN
        EXECUTE format('alter table if exists %s enable row level security', cmd.object_identity);
        RAISE LOG 'rls_auto_enable: enabled RLS on %', cmd.object_identity;
      EXCEPTION
        WHEN OTHERS THEN
          RAISE LOG 'rls_auto_enable: failed to enable RLS on %', cmd.object_identity;
      END;
     ELSE
        RAISE LOG 'rls_auto_enable: skip % (either system schema or not in enforced list: %.)', cmd.object_identity, cmd.schema_name;
     END IF;
  END LOOP;
END;
$function$;

CREATE OR REPLACE FUNCTION public.set_product_location_updated_at()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SET search_path TO 'pg_catalog', 'public'
  AS $function$
begin
  new.updated_at := pg_catalog.now();
  return new;
end;
$function$;

