CREATE VIEW "public"."category_attributes_resolved" WITH (security_invoker=true) AS  WITH RECURSIVE category_ancestors AS (
         SELECT c.id AS id_category,
            c.id AS ancestor_id,
            c.parent_id,
            0 AS distance,
            ARRAY[c.id] AS visited
           FROM public.category c
        UNION ALL
         SELECT a.id_category,
            parent.id AS ancestor_id,
            parent.parent_id,
            (a.distance + 1),
            (a.visited || parent.id)
           FROM (category_ancestors a
             JOIN public.category parent ON ((parent.id = a.parent_id)))
          WHERE (NOT (parent.id = ANY (a.visited)))
        ), effective_rules AS (
         SELECT DISTINCT ON (a.id_category, r_1.id_attribute_def) a.id_category,
            r_1.id_attribute_def,
            r_1.required,
            a.ancestor_id AS source_category_id,
            a.distance
           FROM (category_ancestors a
             JOIN public.category_attribute_rules r_1 ON ((r_1.id_category = a.ancestor_id)))
          ORDER BY a.id_category, r_1.id_attribute_def, a.distance
        )
 SELECT r.id_category,
    d.id AS id_attribute_def,
    d.name,
    d.input_type,
    d.options,
    d.unit,
    r.required,
    r.source_category_id,
    (r.distance > 0) AS is_inherited
   FROM (effective_rules r
     JOIN public.attributes_definitions d ON ((d.id = r.id_attribute_def)));

