CREATE POLICY "Users can insert their avatar" ON "storage"."objects"
  FOR INSERT
  TO "authenticated"
  WITH
    CHECK
    (((bucket_id = 'user-images'::text) AND ((storage.foldername(name))[1] = 'avatars'::text) AND ((storage.foldername(name))[2] = (auth.uid())::text) AND (storage.filename(name) =
    'avatar.jpg'::text)));

CREATE POLICY "Users can select their avatar" ON "storage"."objects"
  FOR SELECT
  TO "authenticated"
  USING
    (((bucket_id = 'user-images'::text) AND ((storage.foldername(name))[1] = 'avatars'::text) AND ((storage.foldername(name))[2] = (auth.uid())::text) AND (storage.filename(name) =
    'avatar.jpg'::text)));

CREATE POLICY "Users can update their avatar" ON "storage"."objects"
  FOR UPDATE
  TO "authenticated"
  USING
    (((bucket_id = 'user-images'::text) AND ((storage.foldername(name))[1] = 'avatars'::text) AND ((storage.foldername(name))[2] = (auth.uid())::text) AND (storage.filename(name) =
    'avatar.jpg'::text)))
  WITH
    CHECK
    (((bucket_id = 'user-images'::text) AND ((storage.foldername(name))[1] = 'avatars'::text) AND ((storage.foldername(name))[2] = (auth.uid())::text) AND (storage.filename(name) =
    'avatar.jpg'::text)));

CREATE EVENT TRIGGER "ensure_rls"
  ON ddl_command_end
  WHEN TAG IN ('CREATE TABLE', 'CREATE TABLE AS', 'SELECT INTO')
  EXECUTE FUNCTION "public"."rls_auto_enable"();

ALTER PUBLICATION "supabase_realtime" ADD TABLE "public"."conversation";

ALTER PUBLICATION "supabase_realtime" ADD TABLE "public"."message_attachment";

ALTER PUBLICATION "supabase_realtime" ADD TABLE "public"."message";

COMMENT ON COLUMN "public"."attributes_definitions"."code" IS 'Stable technical key used by feed filters; must not depend on the displayed/translatable name.';

COMMENT ON COLUMN "public"."category"."parent_id" IS 'Une catégorie peut avoir 0 ou 1 parent, et 0 ou plusieurs enfants (Vêtements -> Pulls, Pantalons...)';

COMMENT ON COLUMN "public"."certification"."is_public" IS 'Allows to see the certification inside the app (paid certifications, enterprises, etc...)';

COMMENT ON COLUMN "public"."message"."message_type" IS 'Le type de message dans les MPs : text | troc_proposal | ou autres';

COMMENT ON COLUMN "public"."product"."share_count" IS 'Le nombre de fois que le produit (article) a été partagé';

COMMENT ON COLUMN "public"."troc"."status" IS 'draft        -- si on persiste les brouillons pending      -- proposition envoyée, attente de réponse accepted     -- acceptée, organisation de l’échange scheduled    -- rendez-vous/livraison défini completed    -- troc finalisé rejected     -- refusée cancelled    -- annulée par l’un des deux expired      -- expiration automatique éventuelle';

COMMENT ON EXTENSION "pgjwt" IS 'JSON Web Token API for Postgresql';

COMMENT ON EXTENSION "postgis" IS 'PostGIS geometry and geography spatial types and functions';

COMMENT ON TABLE "public"."attributes_definitions" IS 'All the different attributes available for a category (color, size, fabric, etc...)';

COMMENT ON TABLE "public"."category" IS 'Available categories for a product on Trocle';

COMMENT ON TABLE "public"."category_attribute_rules" IS 'Whether a category requires certain attribute';

COMMENT ON TABLE "public"."certification" IS 'Les certifications disponibles sur Trocle';

COMMENT ON TABLE "public"."conversation_user" IS 'Allows to know what user belongs to what conversation(s)';

COMMENT ON TABLE "public"."feed_impressions" IS '"Ce produit a réellement été affiché à l’utilisateur dans son feed, ce n''est pas un consultation (clic sur le produit)", pour ça, la table user_product_history existe';

COMMENT ON TABLE "public"."reserved_usernames" IS 'Pseudos réservés (admin, shop etc)';

COMMENT ON TABLE "public"."state" IS 'State of a product';

COMMENT ON TABLE "public"."user_category_preferences" IS 'Product categories preferred by a user on Trocle';

GRANT EXECUTE ON FUNCTION "public"."check_username_availability"(text) TO PUBLIC, "anon", "authenticated", "postgres", "service_role";

REVOKE ALL ON FUNCTION "public"."complete_onboarding"(text, date, text, text, double precision, double precision, bigint[]) FROM PUBLIC;

